using System.Collections;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DecayEffect", menuName = "Data/Battle/Effects/Enemy/Decay Effect")]
public class DecayEffect : Effect
{
	protected override string GetLocalizedDescription()
	{
		return base.localizationManager.GetLocalizedAtTheStartOfItsTurn(withSpace: true) + base.GetLocalizedDescription();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DecayCoroutine(effectAmount, effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	private IEnumerator DecayCoroutine(int effectAmount, GameObject effectOwner)
	{
		PlayEffectActivationSFX();
		SpawnVFX(effectOwner.transform.position, 2f);
		yield return new WaitForSeconds(0.3f);
		effectOwner.GetComponent<CorruptedAnimalCorruptionStats>().ModifyOverCorruption(effectAmount);
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		yield return new WaitForSeconds(0.6f);
	}
}
